  const {
  name, count, mode, show, items, label, value, custom,
  settings, context, locales, amount, date
} = props;
  return (<Subject branch={mode} data-selector={value} data-label={<span>Data {name}</span>} aria-label={label} ref={custom}>Fallback {name}</Subject>);
}

